#pragma once
#include "SwgxrBountyHunterModifiers.h"
#include "CoreCuCombat.h"
#include "PistoleerPolicy.h"
#include "SwgxrPistoleer.h"
#include "SwgxrBlastSight.h"
#include <chrono>
class SwgxrBountyHunter {
 using Json=JSONSerializationType;using Vec=corecu::bountyhunter::Vec;
public:
 static bool clearsArm(const Json& request){auto verb=request.at("action").get<std::string>();
  if(verb=="update" || verb=="snapshot" || verb=="fire" || verb=="impact" || verb=="bountyhunter")return false;
  if(verb=="replication")return request.contains("command");
  if(verb=="inventory")return request.value("inventory_command",std::string("swgxr_inventory_v1"))!="swgxr_inventory_v1";
  auto key=verb=="services"?"service":verb.c_str();if(request.contains(key) && request.at(key).is_object()){auto sub=request.at(key).value("action",std::string("status"));if(sub=="status" || sub=="slicing_status")return false;}
  return true;
 }
 static bool lightning(WeaponObject* w){return w && w->isLightningRifle();}
 static bool scatter(WeaponObject* w){return w && w->getServerObjectCRC()==STRING_HASHCODE("object/weapon/ranged/pistol/pistol_scatter.iff");}
 static bool compatible(CreatureObject* c,const std::string& id=""){auto w=c->getWeapon();if(!w || w->isBroken() || !w->isCertifiedFor(c))return false;auto a=corecu::bountyhunter::ability(id);std::string family=a.family;return family=="pistol"?w->isPistolWeapon():family=="carbine"?w->isCarbineWeapon():(w->isPistolWeapon() || w->isCarbineWeapon() || lightning(w));}
 static bool learned(CreatureObject* c,const std::string& id){auto a=corecu::bountyhunter::ability(id);return *a.skill && c->hasSkill("combat_bountyhunter_novice") && c->hasSkill(a.skill) && c->getPlayerObject() && (!*a.grant || c->getPlayerObject()->hasAbility(a.grant));}
 static int branch(CreatureObject* c,const std::string& id){auto w=c->getWeapon();return SwgxrBountyHunterModifiers::branch(c,id=="eye_shot" || id=="bleeding_shot"?"pistol_speed":id=="confusion_shot" || id=="underhand_shot"?"carbine_speed":w && lightning(w)?"heavy_rifle_lightning_speed":w && w->isPistolWeapon()?"pistol_speed":"carbine_speed");}
 static double chance(CreatureObject* c,const std::string& id,double rating){int progress=branch(c,id);if(id=="underhand_shot" && !c->getPlayerObject()->hasAbility("knockdownFire"))progress=std::min(10,progress);return corecu::bountyhunter::chance(rating,progress);}
 static long long wallMillis(){return std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count();}
 static double cooldown(CreatureObject* c,const std::string& id){auto t=c->getCooldownTime(String(("swgxr_smuggler_"+id).c_str()));double remaining=t?std::max(0.,-t->miliDifference()/1000.):0.;auto ghost=c->getPlayerObject();if(ghost){auto saved=ghost->getScreenPlayData("swgxr_bountyhunter",String((id+"_until").c_str()));if(!saved.isEmpty())try{remaining=std::max(remaining,corecu::clamp((std::stoll(saved.toCharArray())-wallMillis())/1000.,0,120));}catch(...){}}return remaining;}
 static void recover(CreatureObject* c,const std::string& id){int ms=corecu::bountyhunter::ability(id).cooldown*1000;c->addCooldown(String(("swgxr_smuggler_"+id).c_str()),ms);c->getPlayerObject()->setScreenPlayData("swgxr_bountyhunter",String((id+"_until").c_str()),String(std::to_string(wallMillis()+ms).c_str()));}
 static bool conditions(CreatureObject* c,const std::string& id){return compatible(c,id) && !c->isDead() && !c->isIncapacitated() && !c->isRidingMount() && (id!="duelist_stance" || !c->hasBuff(STRING_HASHCODE("swgxr_duelist_stance")));}
 static bool targetReady(CreatureObject* a,const std::string& id){if(!a || !a->isAiAgent() || a->asAiAgent()->isPet() || a->isDead() || a->isIncapacitated())return false;return id!="underhand_shot" || !CoreCuCombat::boss(a);}
 static void refresh(CreatureObject* c){if(!compatible(c) || !learned(c,"duelist_stance") || c->isDead() || c->isIncapacitated())c->removeBuff(STRING_HASHCODE("swgxr_duelist_stance"));}
 static Json projectileProfile(WeaponObject* w){if(scatter(w))return {{"kind","scatter"},{"pellet_count",8},{"half_angle_degrees",4},{"speed",160}};if(lightning(w))return {{"kind","lightning"},{"speed",160},{"acquisition_degrees",5},{"turn_degrees_per_second",20},{"max_turn_degrees",8}};return Json::object();}
 static Json weaponProfile(CreatureObject* c){auto w=c->getWeapon();if(!scatter(w) && !lightning(w))return Json::object();Json out={{"delivery",scatter(w)?"scatter":"guided_bolt"},{"projectile_profile",projectileProfile(w)},{"projectile_speed",160},{"target_cap",1}};if(scatter(w)){out["pellet_count"]=8;out["half_angle_degrees"]=4;}else{out["acquisition_degrees"]=5;out["turn_degrees_per_second"]=20;out["max_turn_degrees"]=8;out["normalized_damage"]=corecu::bountyhunter::lightningDamage(w->getMinDamage(),w->getMaxDamage(),branch(c,""));out["craft_quality_fraction"]=corecu::bountyhunter::lightningQuality(w->getMinDamage(),w->getMaxDamage());}return out;}
 static Json snapshot(CreatureObject* c){refresh(c);Json out=Json::object();for(auto id:{"eye_shot","confusion_shot","underhand_shot","duelist_stance","fast_blast"}){auto a=corecu::bountyhunter::ability(id);out[id]={{"learned",learned(c,id)},{"conditions_met",conditions(c,id)},{"cooldown_remaining_seconds",cooldown(c,id)},{"cooldown_seconds",a.cooldown},{"action_cost",a.action},{"mind_cost",a.mind},{"interval_seconds",a.gesture?.25:c->getWeapon()?double(CombatManager::instance()->calculateWeaponAttackSpeed(c,c->getWeapon(),1)):1.5}};}
  auto buff=c->getBuff(STRING_HASHCODE("swgxr_duelist_stance"));out["duelist_stance"]["active"]=bool(buff);out["duelist_stance"]["active_remaining_seconds"]=buff?std::max(0.f,buff->getTimeLeft()):0.;out["duelist_stance"]["target_id"]=buff && c->getPlayerObject()?std::string(c->getPlayerObject()->getScreenPlayData("swgxr_bountyhunter","duelist_target").toCharArray()):"";out["duelist_stance"]["duration_seconds"]=8;return out;
 }
 static Json abilities(CreatureObject* c){Json out=Json::array();auto state=snapshot(c);for(auto id:{"eye_shot","confusion_shot","underhand_shot","duelist_stance","fast_blast"}){if(!learned(c,id) || !compatible(c,id))continue;auto a=corecu::bountyhunter::ability(id);auto row=state[id];row["id"]=id;row["label"]=a.label;row["activation"]=a.gesture?"bountyhunter_gesture":"native_ranged";row["ultimate"]=a.ultimate;row["native_authority"]=true;row["source_command"]="attack";row["sac_policy"]="fixed";row["base_sac"]={{"health",0},{"action",a.action},{"mind",a.mind}};if(!a.gesture){row["base_sac"]["action"]=corecu::pistoleer::cost(a.action,SwgxrPistoleer::active(c),id);row["base_sac"]["mind"]=corecu::pistoleer::cost(a.mind,SwgxrPistoleer::active(c),id);}row["damage_multiplier"]=a.damage;row["hit_count"]=1;row["target_cap"]=1;row["max_range_m"]=c->getWeapon()->getMaxRange();row["min_range_m"]=0;row["required_profession_skill"]=a.skill;row["status_chance_bonus"]=corecu::bountyhunter::statusBonus(branch(c,id));row["weapon_requirement"]="Certified matching Bounty Hunter weapon; one eligible opponent.";
   std::string key=id;if(key=="eye_shot")row["anatomical_part"]="head";else if(key=="confusion_shot")row["anatomical_part"]="torso";row["description"]=key=="eye_shot"?"One 0.6x hit and resisted -25 enemy accuracy for up to 6 seconds. Shares Suppression Fire's non-stacking channel.":key=="confusion_shot"?"One 0.6x hit and resisted native Stun for up to 3 seconds; shared control recovery.":key=="underhand_shot"?"Arm one physical 0.65x carbine shot for 1.5 seconds. A landed hit may knock down one non-boss enemy for up to 2 seconds; misses consume costs and cooldown.":key=="duelist_stance"?"For 8 seconds, take 15% less direct damage from one bound opponent. Strongest applicable direct protection wins.":"One physical 3.0x Health hit against one opponent. Normal contact and defenses apply.";
   if(a.gesture){row["category"]="gesture";row["trigger_description"]=key=="underhand_shot"?"With both triggers released, lift the low carbine muzzle and return to aim, then deliberately trigger within 1.5 seconds.":"Hold the weapon forward and tap the upper sternum twice with the free open offhand, grip and triggers released, while looking at an enemy.";}if(a.ultimate)row["profession_requirement"]="Master Bounty Hunter";out.push_back(row);
  }return out;
 }
 static void effects(CreatureObject* c,CreatureObject* a,const std::string& id,int damage){if(damage<=0 || !targetReady(a,id) || id=="fast_blast")return;bool kd=id=="underhand_shot",blind=id=="eye_shot",stun=id=="confusion_shot";if(!kd && !blind && !stun)return;int immunity=kd?CommandEffect::KNOCKDOWN:blind?CommandEffect::BLIND:CommandEffect::STUN;if(a->hasEffectImmunity(immunity) || !a->checkCooldownRecovery("corecu_control_recovery") || (kd && (!a->checkKnockdownRecovery() || a->isKnockedDown())))return;
  if(blind && a->hasBuff(STRING_HASHCODE("swgxr_suppression_fire")) && a->getBuff(STRING_HASHCODE("swgxr_suppression_fire"))->getSkillModifierValue("private_accuracy_bonus")<=-25)return;
  a->addCooldown("corecu_control_recovery",8000);double rating=CoreCuCombat::rating(a,kd?corecu::Knockdown:blind?corecu::Blind:corecu::Stun,a->getSkillMod(kd?"knockdown_defense":blind?"blind_defense":"stun_defense"));if(System::random(99)>=chance(c,id,rating))return;int seconds=corecu::statusDuration(corecu::bountyhunter::ability(id).duration,rating);
  if(blind){a->removeBuff(STRING_HASHCODE("swgxr_suppression_fire"));ManagedReference<Buff*> buff=new Buff(a,STRING_HASHCODE("swgxr_suppression_fire"),seconds,BuffType::STATE);Locker lock(buff,a);buff->setSkillModifier("private_accuracy_bonus",-25);a->addBuff(buff);}else if(stun)a->setStunnedState(seconds);else{a->setPosture(CreaturePosture::KNOCKEDDOWN,false,true);a->addCooldown("knockdownRecovery",8000);a->setPostureChangeDelay(seconds*1000);a->removeBuff(STRING_HASHCODE("burstrun"));a->removeBuff(STRING_HASHCODE("retreat"));ManagedReference<AiAgent*> target=a->asAiAgent();Core::getTaskManager()->scheduleTask([target](){Locker lock(target);if(!target->isDead() && !target->isIncapacitated() && target->isKnockedDown() && !target->hasPostureChangeDelay())target->setPosture(CreaturePosture::UPRIGHT,false,true);},"SwgxrBountyHunterStand",seconds*1000+1);}
 }
 static Json gesture(CreatureObject* c,const Json& request){auto id=request.at("ability_id").get<std::string>();auto a=corecu::bountyhunter::ability(id);auto w=c->getWeapon();if(!a.gesture || !learned(c,id) || !conditions(c,id) || !w->isASubChildOf(c) || std::to_string(w->getObjectID())!=request.at("item_id").get<std::string>())throw std::runtime_error("native_bountyhunter_unavailable");if(cooldown(c,id)>0)throw std::runtime_error("native_bountyhunter_cooldown");auto source=dynamic_cast<const CombatQueueCommand*>(c->getZoneServer()->getObjectController()->getQueueCommand("attack"));if(!source || !source->checkStateMask(c) || !source->checkInvalidLocomotions(c))throw std::runtime_error("native_bountyhunter_state");auto p=c->getWorldPosition();Vec feet{{p.getX(),p.getZ(),p.getY()}},origin{},direction{};for(auto key:{"origin","direction"}){auto v=request.at(key);if(!v.is_array() || v.size()!=3)throw std::runtime_error("invalid_bountyhunter_pose");for(int i=0;i<3;++i)if(!v[i].is_number())throw std::runtime_error("invalid_bountyhunter_pose");}for(int i=0;i<3;++i){origin[i]=request["origin"][i].get<double>();direction[i]=request["direction"][i].get<double>();}if(!corecu::pistoleer::validPose(origin,direction,feet))throw std::runtime_error("invalid_bountyhunter_pose");direction=corecu::bountyhunter::normalized(direction);
  Json out={{"success",true},{"operation","bountyhunter"},{"ability_id",id},{"shot_id",request.at("shot_id")},{"item_id",request.at("item_id")},{"hit",false},{"damage",0},{"interval_seconds",.25},{"ham_cost_committed",false}};
  if(id=="underhand_shot"){out["armed"]=true;out["armed_remaining_seconds"]=1.5;return out;}
  auto targetID=request.value("target_id",std::string());if(targetID.empty())throw std::runtime_error("ability_requires_target");auto target=c->getZoneServer()->getObject(std::stoull(targetID));if(!target || !target->isAiAgent() || target->getZone()!=c->getZone())throw std::runtime_error("invalid_bountyhunter_target");Locker lock(target,c);auto victim=target->asAiAgent();auto v=target->getWorldPosition();Vec offset{{v.getX()-origin[0],v.getZ()+1-origin[1],v.getY()-origin[2]}};if(!targetReady(victim,id) || !victim->isAttackableBy(c) || corecu::bountyhunter::angle(direction,offset)>15 || std::sqrt(corecu::bountyhunter::dot(offset,offset))>w->getMaxRange() || !CollisionManager::checkLineOfSight(c,victim))throw std::runtime_error("bountyhunter_target_unavailable");if(c->getWeapon()!=w || !conditions(c,id))throw std::runtime_error("native_bountyhunter_unavailable");if(c->getHAM(3)<=a.action || c->getHAM(6)<=a.mind)throw std::runtime_error("insufficient_ham");c->inflictDamage(c,3,a.action,false,true,false);c->inflictDamage(c,6,a.mind,false,true,false);recover(c,id);c->getPlayerObject()->setScreenPlayData("swgxr_bountyhunter","duelist_target",String(targetID.c_str()));ManagedReference<Buff*> buff=new Buff(c,STRING_HASHCODE("swgxr_duelist_stance"),8,BuffType::STATE);Locker buffLock(buff,c);c->addBuff(buff);out["ham_cost_committed"]=true;out["target_id"]=targetID;return out;
 }
};
